def strip_code_prompts(rst_string: Any) -> object {
    return rst_string.replace('&gt;&gt;&gt; ', '').replace(
        '&gt;&gt;&gt;\n', '\n'
    ).replace(
        '\n...', '\n'
    );
}

"""Function for looping until correct coordinate is found"""
def get_coordinates(
    threshold: Any,
    value: Any,
    step: Any,
    direction: Any,
    current_x: Any,
    current_y: Any
) -> object {
    while (value <= threshold) {
        for _ in range(0, 2) {
            for _ in range(0, step) {
                value += 1;
                if (direction == 0) {
                    current_x += 1;
                } elif (direction == 1) {
                    current_y += 1;
                } elif (direction == 2) {
                    current_x -= 1;
                } elif (direction == 3) {
                    current_y -= 1;
                }
                if (value == threshold) {
                    return (current_x, current_y);
                }
            }
            direction = (direction + 1) % 4;
        }
        step += 1;
    }
}

